"""napari-flima: A Napari plugin for interactive image analysis and segmentation of FLIM data."""__version__ = "0.1.0"import importlib.resources as pkg_resourcesdef get_logo_path():    """    Get the absolute path to the logo file packaged with this plugin.    Assumes the logo is located in the 'resources' folder within the package.    """    with pkg_resources.path("napari_flima.resources", "logo.png") as logo_path:        return str(logo_path)